"""Evaluate repository policies independently of any record's metadata values."""

from collections.abc import Sequence

from .checks import CheckResult, Rule
from .repository_policies import (
    REPOSITORY_POLICIES,
    AutoFill,
    FieldPolicy,
    Requirement,
)


REQUIREMENT_LABELS: dict[Requirement, str] = {
    "required": "Required",
    "optional": "Optional",
    "conditional": "Conditional",
    "system": "No manual input",
    "varies": "Depends on form",
    "unknown": "Unverified",
}
AUTO_FILL_LABELS: dict[AutoFill, str] = {
    "none": "No",
    "generated": "Generated by repository",
    "default": "Default value",
    "selection": "After selection / lookup",
    "detected": "Detected from input",
    "import": "Account / publication import",
    "unknown": "Unverified",
}


def _policy_status(policy: FieldPolicy) -> str:
    """Assess whether the field is ensured for every standard submission.

    Defaults inside optional sections do not guarantee that a section exists.
    PASS describes required/system metadata, not the accuracy of its value.
    """
    if policy.requirement in {"varies", "unknown"} or policy.auto_fill == "unknown":
        return "UNSURE"
    if policy.requirement == "required" or policy.auto_fill == "generated":
        return "PASS"
    return "WARNING"


def evaluate_repository_checks(
    repository: str, rules: Sequence[Rule]
) -> list[CheckResult]:
    """Return one sourced policy result per field in the adapter's catalog.

    No record values or network requests are needed. New unmapped fields remain
    visible as UNSURE until their submission policy has been researched.
    """
    profile = REPOSITORY_POLICIES[repository]
    results = []
    for rule in rules:
        policy = profile.fields.get(rule.field)
        if policy is None:
            policy = FieldPolicy(
                "unknown", "unknown", "Submission policy has not been verified for this field.", (),
            )
        results.append({
            "field": rule.field,
            "label": rule.label,
            "status": _policy_status(policy),
            "kind": "repository-policy",
            "requirement": policy.requirement,
            "requirementLabel": REQUIREMENT_LABELS[policy.requirement],
            "autoFill": policy.auto_fill,
            "autoFillLabel": AUTO_FILL_LABELS[policy.auto_fill],
            "message": policy.note,
            "sources": list(policy.sources),
            "reviewedAt": profile.reviewed_at if policy.sources else None,
            "scope": profile.scope,
        })
    return results
